package com.itsm.changemanagement.controller;
import com.itsm.changemanagement.entity.*;import com.itsm.changemanagement.dto.CreateChangeRequestDTO;import com.fasterxml.jackson.databind.ObjectMapper;import com.itsm.changemanagement.service.ChangeService;import com.itsm.changemanagement.repository.*;import org.springframework.web.bind.annotation.*;import org.springframework.http.*;import org.springframework.data.domain.*;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import java.util.*;import java.time.*;
@RestController @RequestMapping("/api/changes") public class ChangeController {private final ChangeService s;private final ChangeHistoryRepository h;private final ChangeRequestRepository r;private final ObjectMapper mapper;public ChangeController(ChangeService s,ChangeHistoryRepository h,ChangeRequestRepository r,ObjectMapper mapper){this.s=s;this.h=h;this.r=r;this.mapper=mapper;}
 @PostMapping public ResponseEntity<?> create(@Valid @RequestBody CreateChangeRequestDTO dto){return ResponseEntity.status(201).body(s.create(mapper.convertValue(dto,Map.class)));}@GetMapping public Page<ChangeRequest> all(@RequestParam(required=false)String search,@RequestParam(required=false)ChangeStatus status,@RequestParam(required=false)ChangeType type,Pageable p){return s.search(search,status,type,p);}@GetMapping("/{id}")public ChangeRequest get(@PathVariable Long id){return s.get(id);}@PutMapping("/{id}")public ChangeRequest update(@PathVariable Long id,@RequestBody Map<String,Object>b){return s.update(id,b);}@DeleteMapping("/{id}")public ResponseEntity<?> delete(@PathVariable Long id){ChangeRequest c=s.get(id);if(c.getStatus()!=ChangeStatus.DRAFT)throw new com.itsm.changemanagement.exception.ApiExceptions.Conflict("Only DRAFT can be deleted");r.delete(c);return ResponseEntity.noContent().build();}
 @GetMapping("/my-changes")public List<ChangeRequest> mine(@RequestParam String email){return r.findByRequesterEmailIgnoreCase(email);}@GetMapping("/status/{status}")public List<ChangeRequest> status(@PathVariable ChangeStatus status){return r.findByStatus(status);}@GetMapping("/type/{type}")public List<ChangeRequest> type(@PathVariable ChangeType type){return r.findByChangeType(type);}
 @PostMapping("/{id}/submit")public ChangeRequest submit(@PathVariable Long id,@RequestBody(required=false)Map<String,Object>b){return s.transitionPublic(id,ChangeStatus.SUBMITTED,val(b,"performedBy","requester"),"Submitted");}@PostMapping("/{id}/start-assessment")public ChangeRequest startAssessment(@PathVariable Long id,@RequestBody(required=false)Map<String,Object>b){return s.transitionPublic(id,ChangeStatus.ASSESSMENT,val(b,"performedBy","change-analyst"),"Assessment started");}@PostMapping("/{id}/assess")public ChangeRequest assess(@PathVariable Long id,@RequestBody Map<String,Object>b){return s.assess(id,b);}@GetMapping("/{id}/assessment")public ChangeRequest assessment(@PathVariable Long id){return s.get(id);}
 @PostMapping("/{id}/assign")public ChangeRequest assign(@PathVariable Long id,@RequestBody Map<String,Object>b){ChangeRequest c=s.get(id);c.setAssignedAnalyst(val(b,"changeAnalyst",null));c.setTechnicalTeam(val(b,"technicalTeam",null));c.setImplementationTeam(val(b,"implementationTeam",null));c.setChangeManager(val(b,"changeManager",null));c.setAssignedAt(LocalDateTime.now());return s.save(c);}@GetMapping("/{id}/assignments")public Map<String,Object> assignments(@PathVariable Long id){ChangeRequest c=s.get(id);return Map.of("changeAnalyst",Objects.toString(c.getAssignedAnalyst(),""),"technicalTeam",Objects.toString(c.getTechnicalTeam(),""),"implementationTeam",Objects.toString(c.getImplementationTeam(),""),"changeManager",Objects.toString(c.getChangeManager(),""),"assignedAt",Objects.toString(c.getAssignedAt(),""));}
 @PostMapping("/{id}/review")public ChangeRequest review(@PathVariable Long id,@RequestBody Map<String,Object>b){return s.review(id,b);}@PostMapping("/{id}/request-information")public ChangeRequest info(@PathVariable Long id,@RequestBody Map<String,Object>b){b.put("decision","INFO");return s.review(id,b);}@PostMapping("/{id}/approve")public ChangeRequest approve(@PathVariable Long id,@RequestBody Map<String,Object>b){return s.approve(id,b,true);}@PostMapping("/{id}/reject")public ChangeRequest reject(@PathVariable Long id,@RequestBody Map<String,Object>b){return s.approve(id,b,false);}@GetMapping("/{id}/approvals")public List<Map<String,Object>> approvals(@PathVariable Long id){ChangeRequest c=s.get(id);return c.getApprovedAt()==null?List.of():List.of(Map.of("approvedBy",c.getApprovedBy(),"comments",Objects.toString(c.getApprovalComments(),""),"approvedAt",c.getApprovedAt()));}
 @PostMapping("/{id}/schedule")public ChangeRequest schedule(@PathVariable Long id,@RequestBody Map<String,Object>b){ChangeRequest c=s.get(id);if(c.getStatus()!=ChangeStatus.APPROVED)throw new com.itsm.changemanagement.exception.ApiExceptions.Conflict("Only approved changes can be scheduled");c.setPlannedStartDate(LocalDateTime.parse(val(b,"plannedStartDate",null)));c.setPlannedEndDate(LocalDateTime.parse(val(b,"plannedEndDate",null)));if(c.getPlannedEndDate().isBefore(c.getPlannedStartDate()))throw new IllegalArgumentException("End must not precede start");c.setMaintenanceWindow(val(b,"maintenanceWindow",null));c.setScheduledBy(val(b,"scheduledBy",null));c.setScheduledAt(LocalDateTime.now());s.save(c);return s.transitionPublic(id,ChangeStatus.SCHEDULED,c.getScheduledBy(),"Scheduled");}@GetMapping("/{id}/schedule")public Map<String,Object> schedule(@PathVariable Long id){ChangeRequest c=s.get(id);return Map.of("plannedStartDate",Objects.toString(c.getPlannedStartDate(),""),"plannedEndDate",Objects.toString(c.getPlannedEndDate(),""),"maintenanceWindow",Objects.toString(c.getMaintenanceWindow(),""),"scheduledBy",Objects.toString(c.getScheduledBy(),""),"scheduledAt",Objects.toString(c.getScheduledAt(),""));}
 @PostMapping("/{id}/start-implementation")public ChangeRequest start(@PathVariable Long id,@RequestBody Map<String,Object>b){ChangeRequest c=s.get(id);if(c.getStatus()!=ChangeStatus.SCHEDULED)throw new com.itsm.changemanagement.exception.ApiExceptions.Conflict("Only scheduled/approved changes can start");c.setImplementationStartedAt(LocalDateTime.now());c.setImplementationProgress(0);s.save(c);return s.transitionPublic(id,ChangeStatus.IN_PROGRESS,val(b,"performedBy",c.getImplementationTeam()),"Implementation started");}@PutMapping("/{id}/implementation-progress")public ChangeRequest progress(@PathVariable Long id,@RequestBody Map<String,Object>b){ChangeRequest c=s.get(id);if(c.getStatus()!=ChangeStatus.IN_PROGRESS)throw new com.itsm.changemanagement.exception.ApiExceptions.Conflict("Not in progress");int p=Integer.parseInt(val(b,"progress","0"));if(p<0||p>100)throw new IllegalArgumentException("Progress must be 0..100");c.setImplementationProgress(p);c.setImplementationNotes(val(b,"notes",null));return s.save(c);}@PostMapping("/{id}/complete-implementation")public ChangeRequest complete(@PathVariable Long id,@RequestBody Map<String,Object>b){ChangeRequest c=s.get(id);c.setImplementationEndedAt(LocalDateTime.now());c.setImplementationOutcome(val(b,"outcome","SUCCESS"));c.setImplementationNotes(val(b,"notes",c.getImplementationNotes()));s.save(c);if("FAILED".equalsIgnoreCase(c.getImplementationOutcome())){c.setRollbackRequired(true);return s.transitionPublic(id,ChangeStatus.ROLLBACK_IN_PROGRESS,val(b,"performedBy",null),"Implementation failed; rollback initiated");}return s.transitionPublic(id,ChangeStatus.IMPLEMENTED,val(b,"performedBy",null),"Implementation completed");}
 @PostMapping("/{id}/test-results")public ChangeRequest test(@PathVariable Long id,@RequestBody Map<String,Object>b){ChangeRequest c=s.get(id);if(c.getStatus()==ChangeStatus.IMPLEMENTED)s.transitionPublic(id,ChangeStatus.PENDING_VALIDATION,val(b,"testerName",null),"Validation started");c=s.get(id);c.setTestResults(val(b,"testResults",null));c.setTesterName(val(b,"testerName",null));c.setTestingDate(LocalDateTime.now());c.setValidationComments(val(b,"comments",null));c.setValidationStatus(ValidationStatus.valueOf(val(b,"validationStatus","PENDING").toUpperCase()));s.save(c);if(c.getValidationStatus()==ValidationStatus.PASSED)return s.transitionPublic(id,ChangeStatus.VALIDATED,c.getTesterName(),"Validation passed");if(c.getValidationStatus()==ValidationStatus.FAILED){c.setRollbackRequired(true);s.save(c);}return c;}@GetMapping("/{id}/test-results")public Map<String,Object> tests(@PathVariable Long id){ChangeRequest c=s.get(id);return Map.of("testResults",Objects.toString(c.getTestResults(),""),"testerName",Objects.toString(c.getTesterName(),""),"testingDate",Objects.toString(c.getTestingDate(),""),"validationStatus",c.getValidationStatus());}
 @PostMapping("/{id}/rollback")public ChangeRequest rollback(@PathVariable Long id,@RequestBody Map<String,Object>b){ChangeRequest c=s.get(id);if(c.getStatus()!=ChangeStatus.ROLLBACK_IN_PROGRESS&&c.getStatus()!=ChangeStatus.PENDING_VALIDATION)throw new com.itsm.changemanagement.exception.ApiExceptions.Conflict("Rollback is not available in current state");c.setRollbackRequired(true);c.setRollbackReason(val(b,"reason",null));c.setRollbackNotes(val(b,"notes",null));c.setRollbackStartedAt(LocalDateTime.now());c.setRollbackStatus("IN_PROGRESS");if(c.getStatus()!=ChangeStatus.ROLLBACK_IN_PROGRESS)s.transitionPublic(id,ChangeStatus.ROLLBACK_IN_PROGRESS,val(b,"performedBy",null),"Rollback started");return s.save(c);}@PutMapping("/{id}/rollback/complete")public ChangeRequest rollbackComplete(@PathVariable Long id,@RequestBody Map<String,Object>b){ChangeRequest c=s.get(id);if(c.getStatus()!=ChangeStatus.ROLLBACK_IN_PROGRESS)throw new com.itsm.changemanagement.exception.ApiExceptions.Conflict("Rollback not started");c.setRollbackCompletedAt(LocalDateTime.now());c.setRollbackStatus(val(b,"status","COMPLETED"));c.setRollbackNotes(val(b,"notes",c.getRollbackNotes()));s.save(c);return s.transitionPublic(id,ChangeStatus.ROLLED_BACK,val(b,"performedBy",null),"Rollback completed");}
 @PostMapping("/{id}/close")public ChangeRequest close(@PathVariable Long id,@RequestBody Map<String,Object>b){ChangeRequest c=s.get(id);if(c.getStatus()!=ChangeStatus.VALIDATED&&c.getStatus()!=ChangeStatus.ROLLED_BACK)throw new com.itsm.changemanagement.exception.ApiExceptions.Conflict("Only validated or rolled-back changes can close");c.setClosureNotes(val(b,"closureNotes",null));c.setClosedBy(val(b,"closedBy",null));c.setClosedDate(LocalDateTime.now());c.setFinalOutcome(val(b,"finalOutcome",c.getStatus().name()));c.setPostImplementationReview(val(b,"postImplementationReview",null));s.save(c);return s.transitionPublic(id,ChangeStatus.CLOSED,c.getClosedBy(),"Closed");}@PostMapping("/{id}/cancel")public ChangeRequest cancel(@PathVariable Long id,@RequestBody Map<String,Object>b){ChangeRequest c=s.get(id);c.setCancellationReason(val(b,"reason",null));c.setCancelledBy(val(b,"cancelledBy",null));c.setCancelledAt(LocalDateTime.now());s.save(c);return s.transitionPublic(id,ChangeStatus.CANCELLED,c.getCancelledBy(),c.getCancellationReason());}
 @GetMapping("/{id}/history")public List<ChangeHistory> history(@PathVariable Long id){return s.history(id);}@GetMapping("/dashboard/summary")public Map<String,Object> dashboard(){Map<String,Long> statuses=new LinkedHashMap<>(),types=new LinkedHashMap<>(),risks=new LinkedHashMap<>();for(ChangeStatus x:ChangeStatus.values())statuses.put(x.name(),r.countByStatus(x));for(ChangeType x:ChangeType.values())types.put(x.name(),r.countByChangeType(x));for(RiskLevel x:RiskLevel.values())risks.put(x.name(),r.countByRiskLevel(x));return Map.of("totalChanges",r.count(),"byStatus",statuses,"byType",types,"byRisk",risks);}
 private String val(Map<String,Object>b,String k,String d){Object v=b==null?null:b.get(k);return v==null?d:String.valueOf(v);}
}
